-- Seed data for coordination_authorities, sourced from a phone-book style
-- reference document the org owner supplied (AIP/פמ"ת, רש"ת, רת"א, רט"ג/
-- קק"ל, private aerodrome operators, and municipal security contacts).
--
-- Coarse regional circles, not precise boundaries — same convention as
-- aip_reference_zones (0023). Civilian entries (רש"ת/רת"א/civilian
-- airports/private aerodromes/רט"ג/קק"ל/municipal) are used as-given.
--
-- The military-liaison entries (חיל האוויר / מב"א / IAF base towers) could
-- not be independently verified — public search found no trace of them,
-- unlike every civilian category here, which matched independently
-- confirmed sources. They're seeded anyway per the org owner's explicit
-- instruction, but flagged in `notes` so a dispatcher knows to confirm by
-- phone before relying on one for a real operational coordination, not
-- assume it's already field-tested.

insert into coordination_authorities (name, unit_type, phone, backup_phone, notes, center_lng, center_lat, radius_m) values

